using Nancy;
using Nancy.ModelBinding;
using System;
using WMS_HU_Model.Models.Common;
using WMS_HU_Model.Models.Outbound.Formal;
using WMS_HU_Model.Models.Outbound.Integration;
using WMS_HU_Model.Repositories;
using WMS_HU_Model.Services;
using WMS.Infrastructure.Sap;

namespace WMS.Host.Modules
{    public class OutboundPickingModule : NancyModule
    {
        private readonly IOutboundPickingService _pickingService;

        public OutboundPickingModule()
            : base("/api/wms-fg/outbound")
        {
            IOutboundOrderRepository orderRepository = new OutboundOrderRepository();
            _pickingService = new OutboundPickingService(new OutboundPickingRepository(), orderRepository, new HuIdentifierService(new HuIdentifierRepository()));

            Post["/allocations/preview"] = args =>
            {
                var result=_pickingService.PreviewCombined(this.Bind<OutboundCombinedRequest>());
                return result.IsSuccess ? Response.AsJson(ApiResult.Success(result.Data)) : Response.AsJson(ApiResult.Fail(result.Message));
            };
            Post["/allocations/lock"] = args =>
            {
                var result=_pickingService.LockCombined(this.Bind<OutboundCombinedRequest>());
                return result.IsSuccess ? Response.AsJson(ApiResult.Success(result.Data)) : Response.AsJson(ApiResult.Fail(result.Message));
            };
            Get["/allocations/{allocationNo}"] = args =>
            {
                object raw=args.allocationNo;
                var result=_pickingService.GetAllocation(Convert.ToString(raw));
                return result.IsSuccess ? Response.AsJson(ApiResult.Success(result.Data)) : Response.AsJson(ApiResult.Fail(result.Message));
            };
            Post["/allocations/{allocationNo}/confirm-shipment"] = args =>
            {
                object raw=args.allocationNo;
                var task=_pickingService.GetAllocation(Convert.ToString(raw));
                if(!task.IsSuccess) return Response.AsJson(ApiResult.Fail(task.Message));
                if(task.Data.AllocationStatus!="COMPLETED") return Response.AsJson(ApiResult.Fail("整组全部拣完后才允许过账。"));
                var request=this.Bind<SapOutboundPostingControlRequest>();
                if(request==null || string.IsNullOrWhiteSpace(request.RequestId) || request.RequestId.Length>60
                    || string.IsNullOrWhiteSpace(request.Operator) || request.Operator.Length>50)
                    return Response.AsJson(ApiResult.Fail("操作人或请求号无效。"));
                var sap=new SapOutboundPostingService(new SapOutboundPostingRepository(),new S0089SapOutboundPostingClient());
                try
                {
                    foreach(var order in task.Data.Orders)
                    {
                        var result=sap.ConfirmShipment(order.SAPDeliveryNo,new SapOutboundPostingControlRequest {
                            RequestId=request.RequestId+"-"+order.Id,Operator=request.Operator,Remark=request.Remark });
                        if(!result.IsSuccess) return Response.AsJson(ApiResult.Fail(order.SAPDeliveryNo+"："+result.Message));
                        if(result.Data.SapPostingStatus!="SUCCESS")
                            return Response.AsJson(ApiResult.Fail(order.SAPDeliveryNo+"过账未确认成功；已成功成员不会重复提交，请核查失败或未知结果。"));
                    }
                    return Response.AsJson(ApiResult.Success(_pickingService.GetAllocation(Convert.ToString(raw)).Data));
                }
                catch(Exception)
                {
                    return Response.AsJson(ApiResult.Fail("过账或本地收尾未完成，请查询当前状态；已记录成功的成员不会重复过账。"));
                }
            };

            Get["/orders/{vbeln}/prepick-preview"] = args =>
            {
                object rawVbeln = args.vbeln;
                var result = new OutboundPrepickService(orderRepository, new OutboundPrepickRepository())
                    .Preview(Convert.ToString(rawVbeln));
                return result.IsSuccess
                    ? Response.AsJson(ApiResult.Success(result.Data))
                    : Response.AsJson(ApiResult.Fail(result.Message));
            };

            Post["/orders/{vbeln}/preview"] = args =>
            {
                object rawVbeln = args.vbeln;
                string vbeln = Convert.ToString(rawVbeln);
                OperationResult<OutboundPreviewDto> result = _pickingService.Preview(vbeln);
                return result.IsSuccess
                    ? Response.AsJson(ApiResult.Success(result.Data))
                    : Response.AsJson(ApiResult.Fail(result.Message));
            };

            Post["/orders/{vbeln}/start-picking"] = args =>
            {
                object rawVbeln = args.vbeln;
                string vbeln = Convert.ToString(rawVbeln);
                StartPickingRequest request = this.Bind<StartPickingRequest>();
                OperationResult<StartPickingResultDto> result = _pickingService.StartPicking(vbeln, request);
                return result.IsSuccess
                    ? Response.AsJson(ApiResult.Success(result.Data, result.Message))
                    : Response.AsJson(ApiResult.Fail(result.Message));
            };

            Post["/allocations/{allocationNo}/release"] = args =>
            {
                object rawAllocationNo = args.allocationNo;
                string allocationNo = Convert.ToString(rawAllocationNo);
                OutboundActionRequest request = this.Bind<OutboundActionRequest>();
                OperationResult<OutboundActionResultDto> result = _pickingService.ReleaseAllocation(allocationNo, request);
                return result.IsSuccess
                    ? Response.AsJson(ApiResult.Success(result.Data, result.Message))
                    : Response.AsJson(ApiResult.Fail(result.Message));
            };

            Post["/pick-batches/{pickBatchNo}/scan"] = args =>
            {
                object rawPickBatchNo = args.pickBatchNo;
                string pickBatchNo = Convert.ToString(rawPickBatchNo);
                OutboundScanRequest request = this.Bind<OutboundScanRequest>();
                OperationResult<OutboundScanResultDto> result = _pickingService.Scan(pickBatchNo, request);
                return result.IsSuccess
                    ? Response.AsJson(ApiResult.Success(result.Data, result.Message))
                    : Response.AsJson(ApiResult.Fail(result.Message));
            };
        }
    }
}
